-- ============================================================================
-- TSM (The Sealed Market) - 01_schema.sql   (schema v1: slices 1-3)
-- Target: MySQL 8.0.16+ / 8.4 LTS / 9.x   (needs CHECK constraints + generated columns)
--
-- Covers: accounts, admin staff, catalog (brands -> products -> listings),
--         seller applications + documents, audit log.
-- Later slices add: carts, orders, order_items, sell_to_us tickets, reviews,
--         notifications, support tickets, payouts, banners.
--
-- Conventions
--   * IDs are UUID strings, CHAR(36). Generated by the API, not the database.
--   * Money is DECIMAL(10,2) dollars here; the API sends integer cents.
--   * Timestamps are DATETIME(3) holding UTC. The backend connection must use
--     UTC (mysql2: timezone 'Z'; or run `SET time_zone = '+00:00'`).
--   * Collation utf8mb4_0900_ai_ci is accent- AND case-insensitive, so
--     'Pokemon' and 'Pokémon' are the same value (matches the app's
--     Product.belongs(to:) behaviour) and emails/usernames are case-insensitive.
--
-- Re-runnable: drops and recreates every table. DEV ONLY - this wipes data.
-- ============================================================================

USE tsm;

SET FOREIGN_KEY_CHECKS = 0;

DROP VIEW  IF EXISTS v_product_summary;
DROP TABLE IF EXISTS audit_logs;
DROP TABLE IF EXISTS seller_application_documents;
DROP TABLE IF EXISTS seller_applications;
DROP TABLE IF EXISTS listings;
DROP TABLE IF EXISTS seller_profiles;
DROP TABLE IF EXISTS product_images;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS product_types;
DROP TABLE IF EXISTS brands;
DROP TABLE IF EXISTS password_reset_tokens;
DROP TABLE IF EXISTS admin_staff;
DROP TABLE IF EXISTS users;

SET FOREIGN_KEY_CHECKS = 1;

-- ----------------------------------------------------------------------------
-- Accounts
-- ----------------------------------------------------------------------------

CREATE TABLE users (
  id                 CHAR(36)     NOT NULL,
  username           VARCHAR(30)  NOT NULL,
  email              VARCHAR(255) NOT NULL,
  password_hash      VARCHAR(255) NOT NULL,              -- bcrypt; never the password
  phone              VARCHAR(30)  NULL,
  avatar_key         VARCHAR(255) NULL,                  -- object-storage key of profile picture
  status             ENUM('active','suspended','deleted') NOT NULL DEFAULT 'active',
  terms_accepted_at  DATETIME(3)  NOT NULL,              -- required at sign-up (spec 2)
  terms_version      VARCHAR(20)  NOT NULL DEFAULT '1.0',
  email_verified_at  DATETIME(3)  NULL,
  last_login_at      DATETIME(3)  NULL,
  deleted_at         DATETIME(3)  NULL,                  -- account deletion (App Store rule)
  created_at         DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at         DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_username (username),
  UNIQUE KEY uq_users_email (email)
  -- On account deletion: set status='deleted', deleted_at=now, and overwrite
  -- username/email/phone/avatar_key with anonymised values (e.g.
  -- 'deleted_<id8>' and 'deleted+<id>@deleted.invalid') so orders can keep
  -- their history without keeping personal data.
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Admin staff are a SEPARATE login population from app users, so a customer
-- token can never be mistaken for an admin token.
CREATE TABLE admin_staff (
  id             CHAR(36)     NOT NULL,
  email          VARCHAR(255) NOT NULL,
  name           VARCHAR(100) NOT NULL,
  password_hash  VARCHAR(255) NOT NULL,
  role           ENUM('super_admin','admin','support') NOT NULL DEFAULT 'admin',
  status         ENUM('active','disabled') NOT NULL DEFAULT 'active',
  last_login_at  DATETIME(3)  NULL,
  created_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at     DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_admin_staff_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Password reset (deep link tsm://reset-password?token=...). Only a SHA-256
-- hash of the emailed token is stored, so a database leak can't be replayed.
CREATE TABLE password_reset_tokens (
  id          CHAR(36)  NOT NULL,
  user_id     CHAR(36)  NOT NULL,
  token_hash  CHAR(64)  NOT NULL,
  expires_at  DATETIME(3) NOT NULL,
  used_at     DATETIME(3) NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_prt_token_hash (token_hash),
  KEY ix_prt_user (user_id),
  CONSTRAINT fk_prt_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------------
-- Catalog
-- ----------------------------------------------------------------------------

CREATE TABLE brands (
  id          CHAR(36)     NOT NULL,
  name        VARCHAR(60)  NOT NULL,
  sort_order  INT          NOT NULL DEFAULT 0,
  image_key   VARCHAR(255) NULL,
  is_active   TINYINT(1)   NOT NULL DEFAULT 1,
  created_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_brands_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE product_types (
  id          CHAR(36)     NOT NULL,
  name        VARCHAR(60)  NOT NULL,
  sort_order  INT          NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uq_product_types_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE products (
  id               CHAR(36)     NOT NULL,
  brand_id         CHAR(36)     NOT NULL,
  product_type_id  CHAR(36)     NOT NULL,
  name             VARCHAR(160) NOT NULL,
  description      TEXT         NULL,
  thumbnail_key    VARCHAR(255) NULL,                 -- main 1x1 image for shop grids (spec 4)
  is_active        TINYINT(1)   NOT NULL DEFAULT 1,
  created_at       DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at       DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_products_brand_name (brand_id, name),
  KEY ix_products_type (product_type_id),
  CONSTRAINT fk_products_brand FOREIGN KEY (brand_id)        REFERENCES brands (id)        ON DELETE RESTRICT,
  CONSTRAINT fk_products_type  FOREIGN KEY (product_type_id) REFERENCES product_types (id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Up to 3 detail images in 3x4 (spec 5), shown in this order.
CREATE TABLE product_images (
  id          CHAR(36)     NOT NULL,
  product_id  CHAR(36)     NOT NULL,
  slot        TINYINT UNSIGNED NOT NULL,       -- 1..3, display order
  image_key   VARCHAR(255) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_product_images_slot (product_id, slot),
  CONSTRAINT ck_product_images_slot CHECK (slot BETWEEN 1 AND 3),
  CONSTRAINT fk_product_images_product FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------------
-- Sellers
-- ----------------------------------------------------------------------------

-- A row exists only for APPROVED sellers. "Is this user an approved seller?"
-- is simply: EXISTS a seller_profiles row with status='active'.
CREATE TABLE seller_profiles (
  user_id               CHAR(36)      NOT NULL,
  display_name          VARCHAR(80)   NOT NULL,          -- store name shown on listings
  status                ENUM('active','suspended') NOT NULL DEFAULT 'active',
  rating_avg            DECIMAL(3,2)  NOT NULL DEFAULT 0.00,   -- later recomputed from reviews
  rating_count          INT UNSIGNED  NOT NULL DEFAULT 0,
  sales_count           INT UNSIGNED  NOT NULL DEFAULT 0,      -- later recomputed from orders
  approved_at           DATETIME(3)   NOT NULL,
  approved_by_staff_id  CHAR(36)      NULL,
  created_at            DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at            DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (user_id),
  UNIQUE KEY uq_seller_display_name (display_name),
  CONSTRAINT ck_seller_rating CHECK (rating_avg BETWEEN 0 AND 5),
  CONSTRAINT fk_seller_user  FOREIGN KEY (user_id)              REFERENCES users (id)       ON DELETE RESTRICT,
  CONSTRAINT fk_seller_staff FOREIGN KEY (approved_by_staff_id) REFERENCES admin_staff (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- One seller's offer against a product. A seller can only list if they have a
-- seller_profiles row (enforced by the foreign key).
--   * Seller sells out  -> quantity_available = 0 -> that row drops off the product page.
--   * Every seller out  -> product stays visible but grays out "SOLD OUT" (see v_product_summary).
CREATE TABLE listings (
  id                  CHAR(36)       NOT NULL,
  product_id          CHAR(36)       NOT NULL,
  seller_id           CHAR(36)       NOT NULL,           -- = seller_profiles.user_id
  price               DECIMAL(10,2)  NOT NULL,
  source              VARCHAR(100)   NOT NULL,           -- e.g. 'From Case', 'Loose Product'
  box_position        VARCHAR(40)    NULL,               -- e.g. 'Box 4 of 12'
  condition_label     VARCHAR(60)    NOT NULL DEFAULT 'Factory Sealed',  -- CONDITION is a reserved word
  quantity_available  INT UNSIGNED   NOT NULL DEFAULT 0,
  is_active           TINYINT(1)     NOT NULL DEFAULT 1, -- 0 = seller/admin removed it
  created_at          DATETIME(3)    NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at          DATETIME(3)    NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY ix_listings_product_price (product_id, price),
  KEY ix_listings_seller (seller_id),
  CONSTRAINT ck_listings_price CHECK (price > 0),
  CONSTRAINT fk_listings_product FOREIGN KEY (product_id) REFERENCES products (id)              ON DELETE CASCADE,
  CONSTRAINT fk_listings_seller  FOREIGN KEY (seller_id)  REFERENCES seller_profiles (user_id)  ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------------
-- Seller applications (apply -> admin approval)
-- ----------------------------------------------------------------------------

CREATE TABLE seller_applications (
  id                   CHAR(36)      NOT NULL,
  user_id              CHAR(36)      NOT NULL,
  business_name        VARCHAR(160)  NOT NULL,
  business_address     VARCHAR(255)  NOT NULL,
  contact_email        VARCHAR(255)  NOT NULL,
  phone_number         VARCHAR(30)   NULL,
  source_type          ENUM('distributor','retail_store','manufacturer_direct','other','test') NOT NULL,
  distributor_list     TEXT          NOT NULL,           -- comma-separated; feeds the sell-to-us "Source" dropdown
  status               ENUM('submitted','under_review','approved','declined') NOT NULL DEFAULT 'submitted',
  is_test              TINYINT(1)    NOT NULL DEFAULT 0, -- demo "test" shortcut; server must ignore it in production
  decision_note        VARCHAR(500)  NULL,
  reviewed_by_staff_id CHAR(36)      NULL,
  reviewed_at          DATETIME(3)   NULL,
  submitted_at         DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at           DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  -- Trick for "only ONE open application per user": MySQL has no partial
  -- unique index, but UNIQUE ignores NULLs. This column is the user id while
  -- the application is open and NULL once it is approved/declined.
  open_for_user_id     CHAR(36) GENERATED ALWAYS AS (
                         CASE WHEN status IN ('submitted','under_review') THEN user_id ELSE NULL END
                       ) STORED,
  PRIMARY KEY (id),
  UNIQUE KEY uq_one_open_application (open_for_user_id),
  KEY ix_sellerapp_status (status, submitted_at),
  KEY ix_sellerapp_user (user_id),
  CONSTRAINT fk_sellerapp_user  FOREIGN KEY (user_id)              REFERENCES users (id)       ON DELETE RESTRICT,
  CONSTRAINT fk_sellerapp_staff FOREIGN KEY (reviewed_by_staff_id) REFERENCES admin_staff (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Verification documents: city selling permit, business license, tax permit.
-- The file itself lives in private object storage; only its key is stored here.
CREATE TABLE seller_application_documents (
  id                CHAR(36)      NOT NULL,
  application_id    CHAR(36)      NOT NULL,
  doc_type          ENUM('city_permit','business_license','tax_permit','other') NOT NULL DEFAULT 'other',
  original_filename VARCHAR(255)  NOT NULL,
  storage_key       VARCHAR(500)  NOT NULL,
  mime_type         VARCHAR(100)  NOT NULL,
  size_bytes        INT UNSIGNED  NOT NULL,
  uploaded_at       DATETIME(3)   NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY ix_sellerdoc_app (application_id),
  CONSTRAINT fk_sellerdoc_app FOREIGN KEY (application_id) REFERENCES seller_applications (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------------
-- Admin audit log (spec: "Admin audit logs") - append-only by convention.
-- ----------------------------------------------------------------------------

CREATE TABLE audit_logs (
  id           BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  actor_type   ENUM('staff','user','system') NOT NULL,
  actor_id     CHAR(36)     NULL,
  action       VARCHAR(80)  NOT NULL,           -- e.g. 'seller_application.approved'
  entity_type  VARCHAR(60)  NOT NULL,
  entity_id    CHAR(36)     NULL,
  details      JSON         NULL,
  ip_address   VARCHAR(45)  NULL,
  created_at   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY ix_audit_entity (entity_type, entity_id),
  KEY ix_audit_actor  (actor_type, actor_id),
  KEY ix_audit_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------------
-- View: what the shop grid needs per product (lowest price, # of sellers,
-- fully-sold-out flag). Mirrors Product.lowestPrice / sellerCount / isFullySoldOut
-- in the iOS app. The API can query this directly.
-- ----------------------------------------------------------------------------

CREATE VIEW v_product_summary AS
SELECT
  p.id    AS product_id,
  b.name  AS brand,
  pt.name AS product_type,
  p.name  AS product_name,
  MIN(CASE WHEN l.is_active = 1 AND l.quantity_available > 0 THEN l.price END) AS lowest_price,
  COUNT(CASE WHEN l.is_active = 1 AND l.quantity_available > 0 THEN 1 END)     AS seller_count,
  CASE
    WHEN COUNT(CASE WHEN l.is_active = 1 THEN 1 END) > 0
     AND COUNT(CASE WHEN l.is_active = 1 AND l.quantity_available > 0 THEN 1 END) = 0
    THEN 1 ELSE 0
  END AS is_fully_sold_out
FROM products p
JOIN brands b         ON b.id  = p.brand_id
JOIN product_types pt ON pt.id = p.product_type_id
LEFT JOIN listings l  ON l.product_id = p.id
WHERE p.is_active = 1
GROUP BY p.id, b.name, pt.name, p.name;
